import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    close = hist.close

    sma200 = ind.sma(close, 200)
    sma5 = ind.sma(close, 5)
    rsi2 = ind.rsi(close, 2)

    c = float(close[-1])
    s200 = float(sma200[-1])
    s5 = float(sma5[-1])
    r2 = float(rsi2[-1])

    target = float(pos)

    long_entry = (not math.isnan(s200)) and (not math.isnan(r2)) and (c > s200) and (r2 <= 10.0)
    short_entry = (not math.isnan(s200)) and (not math.isnan(r2)) and (c < s200) and (r2 >= 90.0)

    exit_long = (pos > 0.0) and (not math.isnan(s5)) and (c > s5)
    exit_short = (pos < 0.0) and (not math.isnan(s5)) and (c < s5)

    if pos > 0.0:
        if exit_long:
            if short_entry:
                target = -1.0
            else:
                target = 0.0
    elif pos < 0.0:
        if exit_short:
            if long_entry:
                target = 1.0
            else:
                target = 0.0
    else:
        if long_entry:
            target = 1.0
        elif short_entry:
            target = -1.0

    return {"target": target, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    mid = (hist.high + hist.low) / 2.0

    sma20 = ind.sma(mid, 20)
    mean20 = sma20[-1]

    if len(hist) < 52:
        return {"target": pos, "stop": None, "take": None}

    # Population standard deviation over the last 20 midpoints
    window = np.asarray(mid[-20:], dtype=float)
    var = float(np.mean((window - mean20) ** 2))
    sd20 = math.sqrt(var)

    upper = mean20 + 2.0 * sd20

    # Ichimoku cloud spans charted under the current bar:
    # displacement 26, so use spans computed from bars ending 25 bars ago.
    htf = hist
    tenkan_h = ind.highest(htf.high, 9)
    tenkan_l = ind.lowest(htf.low, 9)
    kijun_h = ind.highest(htf.high, 26)
    kijun_l = ind.lowest(htf.low, 26)
    span_a = (tenkan_h + tenkan_l + kijun_h + kijun_l) / 4.0
    span_b = (ind.highest(htf.high, 52) + ind.lowest(htf.low, 52)) / 2.0

    span_a_now = span_a[-26] if len(span_a) > 25 else float("nan")
    span_b_now = span_b[-26] if len(span_b) > 25 else float("nan")

    close = float(hist.close[-1])

    if pos == 0.0:
        if (
            not math.isnan(mean20)
            and not math.isnan(sd20)
            and close > upper
            and close > span_a_now
            and close > span_b_now
        ):
            return {"target": 1.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    if pos > 0.0:
        if not math.isnan(mean20) and close < mean20:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    n = len(hist)
    period_ms = 31 * 24 * 60 * 60 * 1000
    trail_pct = 0.01

    t = int(hist.time[-1])

    if "start_time" not in state:
        state["start_time"] = t
        state["high_close"] = float(hist.close[-1])
        state["in_trade"] = False
        state["last_period"] = 0

    start_time = int(state["start_time"])
    period_idx = (t - start_time) // period_ms
    in_trade = bool(state["in_trade"])
    high_close = float(state["high_close"])
    last_period = int(state["last_period"])

    if period_idx > last_period:
        state["last_period"] = period_idx
        last_period = period_idx

    if pos > 0:
        in_trade = True
    elif pos == 0:
        in_trade = False

    close = float(hist.close[-1])

    if pos > 0 or (not in_trade and period_idx >= 0):
        if pos <= 0 and period_idx == 0 and n == 960:
            state["high_close"] = close
            state["in_trade"] = True
            return {"target": 1.0, "stop": None, "take": None}

    if pos > 0:
        if close > high_close:
            high_close = close
            state["high_close"] = high_close
            state["in_trade"] = True
            return {"target": pos, "stop": high_close * (1.0 - trail_pct), "take": None}
        if close < high_close * (1.0 - trail_pct):
            state["in_trade"] = False
            state["high_close"] = high_close
            return {"target": 0.0, "stop": None, "take": None}
        state["high_close"] = high_close
        state["in_trade"] = True
        return {"target": pos, "stop": high_close * (1.0 - trail_pct), "take": None}

    if not in_trade:
        if period_idx > last_period or (n == 960):
            state["high_close"] = close
            state["in_trade"] = True
            return {"target": 1.0, "stop": None, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    state["high_close"] = high_close
    state["in_trade"] = in_trade
    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    if pos == 0.0:
        if len(hist) < 1:
            return {"target": 1.0, "stop": None, "take": None}
        ref = float(hist.close[-1])
        return {
            "target": 1.0,
            "stop": ref * 0.997,
            "take": ref * 1.003,
        }

